using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Diagnostics;using System.Windows;using System.Windows.Controls;using System.Web.Script.Serialization;using DualSteam.UI;using DualSteam;
public partial class App {
 TextBlock updatesStatus,updateDetail,updateChecked;ProgressBar updateProgress;Button updateCheckButton,updateInstallButton,cancelDownload;readonly UpdateFeedback updateFeedback=new UpdateFeedback();ReleaseInfo availableRelease;bool checkingUpdates;DateTime nextUpdate=DateTime.MinValue;string notifiedVersion;System.Threading.CancellationTokenSource updateCancellation;
 void BeginSetup(){if(!ServiceReady())return;var wizard=new SetupWizard(Engine.DetectSteam()){Owner=window};if(wizard.ShowDialog()==true)Act(()=>SetupService.Provision(wizard.SteamPath,wizard.DataPath),"Second Steam is ready. Open it and sign in to your second account.",secondCard);}
 void UpdateFeedbackView(){if(updatesStatus==null)return;updatesStatus.Text=updateFeedback.Title;updateDetail.Text=updateFeedback.Detail;updateChecked.Text=updateFeedback.LastChecked.HasValue?"Last checked: "+updateFeedback.LastChecked.Value.ToString("G"):"Not checked in this session";updateProgress.Visibility=checkingUpdates||updateCancellation!=null?Visibility.Visible:Visibility.Collapsed;if(cancelDownload!=null)cancelDownload.Visibility=updateCancellation!=null?Visibility.Visible:Visibility.Collapsed;updateCheckButton.Content=checkingUpdates?"Checking…":"Check for updates";updateCheckButton.IsEnabled=!checkingUpdates&&!busy;updateInstallButton.IsEnabled=availableRelease!=null&&!checkingUpdates&&!busy;}
 async void CheckUpdates(bool manual=false){
  if(manual){ShowManager();if(page!="Updates")ShowPage("Updates");}
  if(checkingUpdates)return;if(busy){if(manual)toast.Show("Wait for the current operation to finish.");return;}
  checkingUpdates=true;nextUpdate=DateTime.UtcNow.AddMinutes(30);availableRelease=null;updateFeedback.Begin();UpdateFeedbackView();
  try{var request=Task.Run(()=>UpdateService.GetLatest());if(manual)await Task.WhenAll(request,Task.Delay(700));var release=await request;availableRelease=release.Version>UpdateService.ParseVersion(UpdateService.CurrentVersion)?release:null;nextUpdate=DateTime.UtcNow.AddHours(6);updateFeedback.Complete(UpdateService.ParseVersion(UpdateService.CurrentVersion),release.Version);
   if(!manual&&availableRelease!=null&&notifiedVersion!=release.Tag){notifiedVersion=release.Tag;ShowManager();if(page!="Updates")ShowPage("Updates");if(AppDialog.Show(window,"Version "+release.Tag+" is available. Your accounts and game files will be preserved.\n\nDownload and install this update? Quit Second Steam first.","Dual Steam update",MessageBoxButton.YesNo,MessageBoxImage.Information)==MessageBoxResult.Yes){var pendingInstall=Dispatcher.BeginInvoke(new Action(InstallUpdate));}}
  }catch(Exception ex){availableRelease=null;updateFeedback.Fail(ex.Message);Engine.Log("Update check: "+ex.Message);}finally{if(!startupAuthorized&&serviceDecision=="update"&&startupPolicy!=null&&startupPolicy.Release!=null){var required=startupPolicy.Release;availableRelease=new ReleaseInfo{Tag=required.Tag,Version=ServicePolicy.Version(startupPolicy.RequiredVersion),Page="https://github.com/"+UpdateService.Repository+"/releases/tag/"+required.Tag,Download=required.Url,Sha256=required.Sha256,Size=required.Size};updateFeedback.Title="Update required";updateFeedback.Detail="Install "+startupPolicy.RequiredVersion+" to authorize this startup.";}checkingUpdates=false;UpdateFeedbackView();}
 }
 async void InstallUpdate(){
  if(busy||checkingUpdates)return;if(availableRelease==null){CheckUpdates(true);return;}ShowManager();if(page!="Updates")ShowPage("Updates");busy=true;updateCancellation=new System.Threading.CancellationTokenSource();UpdateFeedbackView();
  try{var release=availableRelease;await Task.Run(()=>Engine.PrepareUpdate());updateFeedback.Kind="downloading";updateFeedback.Title="Downloading update";updateFeedback.Detail="Connecting to GitHub. Slow connections are retried automatically.";UpdateFeedbackView();
   string package=await Task.Run(()=>UpdateService.Download(release,(done,total)=>Dispatcher.BeginInvoke(new Action(()=>{if(updateCancellation==null)return;if(updateProgress!=null){updateProgress.IsIndeterminate=done==0;updateProgress.Maximum=100;updateProgress.Value=100.0*done/total;}updateFeedback.Title="Downloading update · "+(100*done/total)+"%";updateFeedback.Detail=(done/1024).ToString("N0")+" / "+(total/1024).ToString("N0")+" KB · verifying SHA-256 before installation";UpdateFeedbackView();})),updateCancellation.Token));updateCancellation.Token.ThrowIfCancellationRequested();
   string folder=Path.GetDirectoryName(package);var request=new UpdateRequest{Target=Engine.Home,Package=package,Sha256=release.Sha256,Version=release.Version.ToString(),ManagerPid=Process.GetCurrentProcess().Id,ManagerStartTicks=Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks};string file=Path.Combine(folder,"request.json");File.WriteAllText(file,new JavaScriptSerializer().Serialize(request));string updater=Path.Combine(folder,"Dual Steam Updater.exe");File.Copy(Path.Combine(Engine.Home,"Dual Steam Updater.exe"),updater);Process.Start(new ProcessStartInfo(updater,"--request "+Engine.Quote(file)){UseShellExecute=true});ShutdownManager();
  }catch(OperationCanceledException){updateFeedback.Kind="canceled";updateFeedback.Title="Download canceled";updateFeedback.Detail="No update was installed. Retry or download the ZIP in your browser.";}
  catch(Exception ex){Engine.Log("Update install: "+ex);updateFeedback.Fail(ex.Message);if(!exitAfterOperation)AppDialog.Show(window,ex.Message,"Update not installed",MessageBoxButton.OK,MessageBoxImage.Information);}
  finally{updateCancellation.Dispose();updateCancellation=null;busy=false;UpdateFeedbackView();if(exitAfterOperation&&!exitRequested){exitAfterOperation=false;ExitManager();}}
 }
 FrameworkElement UpdatesPage(){
  var body=Stack();Heading("Updates","Stable releases from GitHub. Your profiles stay in place.",body);
  updatesStatus=Text(updateFeedback.Title,18,"text.primary",true);updateDetail=Text(updateFeedback.Detail,13,"text.secondary");updateDetail.Margin=new Thickness(0,8,0,0);updateChecked=Text("",12,"text.muted");updateChecked.Margin=new Thickness(0,12,0,0);updateProgress=new ProgressBar{IsIndeterminate=true,Height=4,Margin=new Thickness(0,16,0,0)};Theme.Bind(updateProgress,Control.ForegroundProperty,"accent.default");Ui.Name(updateProgress,"Checking GitHub for updates");System.Windows.Automation.AutomationProperties.SetAutomationId(updateProgress,"UpdateCheckProgress");System.Windows.Automation.AutomationProperties.SetAutomationId(updatesStatus,"UpdateResult");System.Windows.Automation.AutomationProperties.SetAutomationId(updateChecked,"UpdateLastChecked");body.Children.Add(Group(updatesStatus,updateDetail,updateChecked,updateProgress));
  body.Children.Add(Choice("Notify me about updates during this session",Preferences.Current.AutoUpdates,v=>Preferences.Current.AutoUpdates=v));body.Children.Add(Text("Every stable public release is required at the next full startup. Startup availability is always checked, even if notifications are disabled. Open sessions continue working. Optional checks run every six hours. Downloads are checked against GitHub’s SHA-256 digest and backed up before installation.",13,"text.secondary"));
  var actions=new WrapPanel();updateCheckButton=ActionButton("Check for updates",()=>CheckUpdates(true),true);Ui.Name(updateCheckButton,"Check for updates");System.Windows.Automation.AutomationProperties.SetAutomationId(updateCheckButton,"UpdateCheckButton");updateCheckButton.Margin=new Thickness(0,16,8,8);actions.Children.Add(updateCheckButton);updateInstallButton=ActionButton("Install update",InstallUpdate);updateInstallButton.Margin=new Thickness(0,16,0,8);actions.Children.Add(updateInstallButton);cancelDownload=ActionButton("Cancel download",()=>{if(updateCancellation!=null)updateCancellation.Cancel();});cancelDownload.Visibility=Visibility.Collapsed;actions.Children.Add(cancelDownload);actions.Children.Add(ActionButton("Download ZIP in browser",()=>OpenPath(availableRelease==null?"https://github.com/"+UpdateService.Repository+"/releases/latest":availableRelease.Download)));body.Children.Add(actions);body.Children.Add(ActionButton("View releases on GitHub",()=>OpenPath("https://github.com/"+UpdateService.Repository+"/releases")));UpdateFeedbackView();return body;
